content.text:
{
  "name": "标量计数通道选择组件",
  "name_en": "Scaler Channel Selector",
  "manufacturer": "",
  "description": "用于 EPICS SynApps 标量记录的非物理软件组件。它主要负责匹配通道名称、批量匹配名称以及选择要使用的计数通道，适合在实验采集流程中组织和定位标量计数器的通道配置。",
  "description_en": "A non-physical software component for EPICS SynApps scaler records. It is mainly used to match channel names, match multiple names in batch, and select counting channels for use in experimental data-acquisition workflows.",
  "actions": [
    {
      "action_name": "auto-match_name",
      "description": "匹配单个通道名称。",
      "description_en": "Match a single channel name."
    },
    {
      "action_name": "auto-match_names",
      "description": "批量匹配多个通道名称。",
      "description_en": "Match multiple channel names in batch."
    },
    {
      "action_name": "auto-select_channels",
      "description": "选择要使用的通道。",
      "description_en": "Select channels to use."
    }
  ],
  "tag_hints": [
    "EPICS",
    "SynApps scaler record",
    "channel selection",
    "name matching",
    "counter channels",
    "beamline controls"
  ]
}

